def iv(s, v):
    u = s.strip()[2:-2].replace('\\le', '<=').replace('\\ge', '>=')
    if u.startswith(v + ' '):
        return value(u).as_set()
    L, Rt = u.split(' ' + v + ' ')
    return value(L + ' ' + v).as_set() & value(v + ' ' + Rt).as_set()
x = symbols('x')
S = solve_univariate_inequality(x + 3 > -2, x, relational=False) & solve_univariate_inequality(x + 3 <= 7, x, relational=False)
assert S == Interval.Lopen(-5, 4)
ok = [k for k in choices if iv(choices[k], 'x') == S]
assert ok == [answer]
